INSERT INTO `careers` (`id`, `slug`, `title`, `vacancy`, `status`, `location`, `salary`, `description`, `apply_email`, `apply_link`, `created_at`, `updated_at`, `user_id`) VALUES
(1, 'language-trainer-english-arabic-2', 'Language Trainer (English & Arabic)', '2', 'Full-time', 'Dhaka', '35000 - 40000', '<p style=\"border: 0px; margin-right: 0px; margin-bottom: 1.5em; margin-left: 0px; padding: 0px; color: rgb(58, 58, 58); font-family: Montserrat, sans-serif; font-size: 17px;\"><span style=\"border: 0px; margin: 0px; padding: 0px; font-weight: 700;\">Job Context:<br></span><span style=\"border: 0px; margin: 0px; padding: 0px; font-weight: 700;\"><br>Bangladesh Human Capital, Recruiting License, RL-1557</span>&nbsp;is one of the leading Govt. approved ISO 9001 certified overseas Recruiting solutions company based in Dhaka, Bangladesh. BHC specializes in providing both skilled and semi-skilled workforces all over the world. To full-fill our vision we are Looking for an individual who will work in the operation department as a&nbsp;<span style=\"border: 0px; margin: 0px; padding: 0px; font-weight: 700;\">“Language Trainer”</span>&nbsp;as earliest as possible.</p><p style=\"border: 0px; margin-right: 0px; margin-bottom: 1.5em; margin-left: 0px; padding: 0px; color: rgb(58, 58, 58); font-family: Montserrat, sans-serif; font-size: 17px;\"><span style=\"border: 0px; margin: 0px; padding: 0px; font-weight: 700;\">&nbsp;</span><span style=\"border: 0px; margin: 0px; padding: 0px; font-weight: 700;\">Job Responsibilities:</span></p><ul style=\"border: 0px; margin-right: 0px; margin-bottom: 1.5em; margin-left: 3em; padding: 0px; list-style-position: initial; list-style-image: initial; color: rgb(58, 58, 58); font-family: Montserrat, sans-serif; font-size: 17px;\"><li style=\"border: 0px; margin: 0px; padding: 0px;\">Good understanding &amp; speaking capability in Arabic.</li><li style=\"border: 0px; margin: 0px; padding: 0px;\">Write an application on the Arabic language, and translate the Arabic language into English as well as Bangla.</li><li style=\"border: 0px; margin: 0px; padding: 0px;\">Provide training &amp; orientation to job seekers in Arabic &amp; English both languages.</li><li style=\"border: 0px; margin: 0px; padding: 0px;\">Manage daily official works on the desk.</li><li style=\"border: 0px; margin: 0px; padding: 0px;\">Co-operate with Saudi delegates and clients.</li><li style=\"border: 0px; margin: 0px; padding: 0px;\">Manage computer-related tasks and communication with Saudi delegates.</li><li style=\"border: 0px; margin: 0px; padding: 0px;\">Assist operation department with daily tasks related to visa processing necessities.</li></ul><p style=\"border: 0px; margin-right: 0px; margin-bottom: 1.5em; margin-left: 0px; padding: 0px; color: rgb(58, 58, 58); font-family: Montserrat, sans-serif; font-size: 17px;\"><span style=\"border: 0px; margin: 0px; padding: 0px; font-weight: 700;\">Educational Requirements:</span></p><ul style=\"border: 0px; margin-right: 0px; margin-bottom: 1.5em; margin-left: 3em; padding: 0px; list-style-position: initial; list-style-image: initial; color: rgb(58, 58, 58); font-family: Montserrat, sans-serif; font-size: 17px;\"><li style=\"border: 0px; margin: 0px; padding: 0px;\">Candidate must be graduated from any reputed university of Saudi Arabia, in the Arabic language.</li></ul><p style=\"border: 0px; margin-right: 0px; margin-bottom: 1.5em; margin-left: 0px; padding: 0px; color: rgb(58, 58, 58); font-family: Montserrat, sans-serif; font-size: 17px;\"><span style=\"border: 0px; margin: 0px; padding: 0px; font-weight: 700;\">Experience Requirements:</span></p><ul style=\"border: 0px; margin-right: 0px; margin-bottom: 1.5em; margin-left: 3em; padding: 0px; list-style-position: initial; list-style-image: initial; color: rgb(58, 58, 58); font-family: Montserrat, sans-serif; font-size: 17px;\"><li style=\"border: 0px; margin: 0px; padding: 0px;\">Not required</li></ul><p style=\"border: 0px; margin-right: 0px; margin-bottom: 1.5em; margin-left: 0px; padding: 0px; color: rgb(58, 58, 58); font-family: Montserrat, sans-serif; font-size: 17px;\"><span style=\"border: 0px; margin: 0px; padding: 0px; font-weight: 700;\">Additional Requirements:</span></p><ul style=\"border: 0px; margin-right: 0px; margin-bottom: 1.5em; margin-left: 3em; padding: 0px; list-style-position: initial; list-style-image: initial; color: rgb(58, 58, 58); font-family: Montserrat, sans-serif; font-size: 17px;\"><li style=\"border: 0px; margin: 0px; padding: 0px;\">Age limit up to 40 years old.</li><li style=\"border: 0px; margin: 0px; padding: 0px;\">Only male candidates are allowed to apply.</li><li style=\"border: 0px; margin: 0px; padding: 0px;\">Must have sound English knowledge.</li><li style=\"border: 0px; margin: 0px; padding: 0px;\">Proactive, Self-motivated, and self-starter with a positive attitude.</li><li style=\"border: 0px; margin: 0px; padding: 0px;\">Solid Microsoft Office skills are including Word, Excel, PowerPoint along with email management and internet surfing.</li></ul><p style=\"border: 0px; margin-right: 0px; margin-bottom: 1.5em; margin-left: 0px; padding: 0px; color: rgb(58, 58, 58); font-family: Montserrat, sans-serif; font-size: 17px;\"><span style=\"border: 0px; margin: 0px; padding: 0px; font-weight: 700;\">Compensation &amp; Other Benefits:</span></p><ul style=\"border: 0px; margin-right: 0px; margin-bottom: 1.5em; margin-left: 3em; padding: 0px; list-style-position: initial; list-style-image: initial; color: rgb(58, 58, 58); font-family: Montserrat, sans-serif; font-size: 17px;\"><li style=\"border: 0px; margin: 0px; padding: 0px;\">Festival Bonus: 2</li><li style=\"border: 0px; margin: 0px; padding: 0px;\">Additional bonus -2 or 3</li><li style=\"border: 0px; margin: 0px; padding: 0px;\">Lunch provided</li><li style=\"border: 0px; margin: 0px; padding: 0px;\">Skill development program</li><li style=\"border: 0px; margin: 0px; padding: 0px;\">Business tour</li><li style=\"border: 0px; margin: 0px; padding: 0px;\">Annual picnic</li><li style=\"border: 0px; margin: 0px; padding: 0px;\">Gift for the family</li></ul>', 'career@arobicbd.net', 'https://bdjobs.com/test', '2022-09-18 23:33:53', '2022-09-19 01:16:59', 1);
