INSERT INTO `our_stories` (`id`, `title`, `description`, `who_we_are`, `our_mission`, `our_vision`, `image_path`, `created_at`, `updated_at`, `user_id`) VALUES
(1, 'OUR STORY', 'Our team comes with the experience and knowledge', '<p class=\"MsoNormal\" style=\"text-align:justify;line-height:150%\"><span style=\"font-size: 12pt; line-height: 150%; font-family: &quot;Times New Roman&quot;, serif; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\"><span style=\"font-family: Helvetica;\">Arobic Recruitment Consultant is established on 2017, by\r\nexporting manpower we are firmly promised to introduce our firm as well as\r\nBangladesh as respectful country. Arobic is an extraordinary firm then others\r\nwho has rules and regulations.</span></span></p><p><span style=\"font-family: Helvetica;\">\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n</span></p><p class=\"MsoNormal\" style=\"text-align:justify;line-height:150%\"><span style=\"line-height: 150%; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\"><font face=\"Helvetica\"><span style=\"font-size: 12pt;\">We feel please to introduce the same in our professional\r\nexcept technical training in discipline, </span>honor<span style=\"font-size: 12pt;\">, ideal life including\r\ninternational culture. We shall welcome to take service from our firm. We wish\r\ngood luck for all.</span></font></span></p>', '<p class=\"MsoNormal\" style=\"text-align:justify\"><span style=\"font-family: Helvetica;\">Purpose of our professional work\r\nin charge of time to prize some modern and alternative than international\r\nstandard. Our purpose by more analysis by keeping priority QHSE in the light of\r\npowerful shape in the labour market in the world which is the name of mother in\r\nBangladesh through including name of Arobic Recruitment consultant for\r\nestablishing activities to plan for going last extent of Arobic Recruitment Consultant.\r\nWe love our country then more love humanity.</span><o:p></o:p></p>', '<p class=\"MsoNormal\" style=\"text-align:justify\"><span style=\"font-family: Helvetica; font-size: 11pt; text-align: left;\">Whereas A</span><span style=\"font-family: Helvetica;\">robic Recruitment Consultant\r\nconduct its farm carefully with suitable stuff so it is promised to search in\r\nmodern means for full self-feeling purpose. Our purpose become better solver\r\nfor our professional work and by overcome demand of customer for satisfaction\r\nengaged ourselves as endless guide. Our purpose to strong value health security\r\nenvironment management system to keeping one step ahead them local and\r\ninternational standard.</span><o:p></o:p></p>', '631f1e356ec10-OUR STORY.jpg', '2022-09-12 05:50:08', '2022-09-22 11:37:01', 1);
