(1, 'Our Profile', '<p class=\"MsoNormal\" style=\"text-align:justify;line-height:150%\"><span style=\"font-size: 12pt; line-height: 150%; font-family: &quot;Times New Roman&quot;, serif; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\"><font color=\"#636363\"><span style=\"font-family: Helvetica;\">Arobic Recruitment Consultant, was founded by </span><b><span style=\"font-family: Helvetica;\">Md Mobarak Hosen</span></b><span style=\"font-family: Helvetica;\">. Arobic is principally\r\nengaged in skill worth Development. Arobic occupies Head Office around 4500sq\r\nft in Dhaka, Bangladesh.The well trained workforce of 30 staffs, lead by the\r\nManaging Director </span><b><span style=\"font-family: Helvetica;\">Md. Mobarak Hosen</span></b><span style=\"font-family: Helvetica;\">\r\nand his dynamic management team has position AROBIC RECRUITMEN CONSULTANT as\r\none of the growing high skiIl Recruitment office in Dhaka Bangladesh.\r\nCurrently, we are sending skill worker to the following country.</span></font><o:p></o:p></span></p>', '63295693d570a-Our Profile.pdf', '2022-09-19 06:19:57', '2022-09-22 11:41:15', 1);
INSERT INTO `services` (`id`, `slug`, `title`, `image_path`, `short_desc`, `description`, `created_at`, `updated_at`, `user_id`) VALUES
(1, 'hotel-catering-hospitality-2', 'Hotel/Catering/Hospitality.', '6321b04a64f12-Hotel-Catering-Hospitality.jpg', 'Our workers loads and unloads plates, silverware, and other service equipment. Serves courses, clears dishware, and ensure that guests dining needs are taken care of', '<p><span style=\"color: rgb(0, 0, 0); font-family: Roboto, sans-serif; font-size: 17px;\">Our workers loads and unloads plates, silverware, and other service equipment. Serves courses, clears dishware, and ensure that guests dining needs are taken care of. Keeps serving stations restocked throughout the event. Cleans large and small trays and tray stands to be ready for service.</span></p><p style=\"border: 0px; margin-right: 0px; margin-bottom: 1.5em; margin-left: 0px; padding: 0px; color: rgb(0, 0, 0); font-family: Roboto, sans-serif; font-size: 17px;\">Our workers work in hospitality professionals in event management, public relations agencies, entertainment sector, hotel and resort business, tourism industry, customer service, sales and marketing, spas, cruisers, etc.</p><p style=\"border: 0px; margin-right: 0px; margin-bottom: 1.5em; margin-left: 0px; padding: 0px; color: rgb(0, 0, 0); font-family: Roboto, sans-serif; font-size: 17px;\">Performs hospitality responsibilities through challenges when dealing with overseas clients and customers. They know the cultural values ​​and customs you need to be able to serve them to their satisfaction. The purpose is not just to satisfy them but to impress the customers and get them back</p><p><br></p>', '2022-09-14 04:43:22', '2025-08-27 05:03:26', 1);
